// Instale a Vercel CLI no seu terminal
npm i -g vercel

// Para fazer o deploy do seu projeto local, basta digitar:
vercel

{
  "version": 2,
  "builds": [
    { "src": "package.json", "use": "@vercel/static-build" }
  ]
}

{
  "name": "meu-projeto-hospedado",
  "scripts": {
    "build": "next build",
    "start": "next start"
  }
}

{
  "cleanUrls": true,
  "trailingSlash": false,
  "headers": [
    {
      "source": "/(.*)",
      "headers": [ { "key": "x-custom-header", "value": "vercel-rocks" } ]
    }
  ]
}

import { useState } from 'react';

export default function App() {
  return <h1>Minha Ideia no Ar pela Vercel!</h1>;
}

{
  "redirects": [
    {
      "source": "/sobre-nos",
      "destination": "/sobre.html",
      "permanent": true
    }
  ]
}

// Ao invés de configurar o Express num servidor fixo:
// const express = require('express');
// const app = express();
// app.listen(3000);

// Na Vercel, você foca na função e a plataforma gerencia o servidor.

{
  "buildCommand": "npm run build",
  "outputDirectory": "dist",
  "framework": "vite"
}

// api/hello.js
export default function handler(req, res) {
  res.status(200).json({ 
    message: 'Olá da Função Serverless Vercel!' 
  });
}

// api/user.ts
import type { VercelRequest, VercelResponse } from '@vercel/node';

export default function handler(req: VercelRequest, res: VercelResponse) {
  const { id } = req.query;
  res.status(200).send(`Dados do usuário: ${id}`);
}

{
  "github": {
    "enabled": true,
    "silent": false
  }
}

// Arquivo vercel.json limitando a branch de produção
{
  "git": {
    "deploymentEnabled": {
      "main": true
    }
  }
}

// Exemplo de URLs geradas pela Vercel
// Produção: meusite.com
// Branch de Feature: meusite-git-feature-design-username.vercel.app

import { VercelToolbar } from '@vercel/toolbar/next';

export default function Layout({ children }) {
  return (
    <body>
      {children}
      <VercelToolbar />
    </body>
  );
}

// Você pode verificar o ambiente atual no código
if (process.env.VERCEL_ENV === 'production') {
  console.log('Rodando no domínio oficial!');
} else if (process.env.VERCEL_ENV === 'preview') {
  console.log('Rodando em um deploy de teste!');
}

// Configuração no vercel.json para redirecionar um domínio
{
  "redirects": [
    {
      "source": "/:path*",
      "has": [{ "type": "host", "value": "www.meusite.com" }],
      "destination": "https://meusite.com/:path*",
      "permanent": true
    }
  ]
}

// A Vercel força o tráfego seguro por padrão, sem código extra
// Qualquer acesso a http://meusite.com
// será redirecionado para https://meusite.com com status 308.

{
  "headers": [
    {
      "source": "/(.*)",
      "headers": [
        {
          "key": "Strict-Transport-Security",
          "value": "max-age=63072000; includeSubDomains; preload"
        }
      ]
    }
  ]
}

// Exemplo de acesso a uma variável de ambiente de forma segura na API
export default function handler(req, res) {
  const apiKey = process.env.OPENAI_API_KEY;
  // A chave de API nunca é exposta para o cliente (navegador)
  res.status(200).json({ ok: true });
}

import db from './database';

// No Preview, o banco será 'fake_db', na Produção, 'prod_db'
const url = process.env.DATABASE_URL;
db.connect(url);

// Um erro aqui quebra o build e previne o deploy de ir ao ar:
function Componente() {
  return <div>Erro de sintaxe faltando chaves // falhará no build
}

// Exemplo no vercel.json de um comando de build customizado
{
  "buildCommand": "npm run build && npm run generate-sitemap"
}

{
  "dependencies": {
    "svelte": "^3.0.0",
    "@sveltejs/kit": "^1.0.0"
  }
  // A Vercel lê isso e sabe que deve aplicar as configurações do SvelteKit.
}

// No vercel.json você pode forçar o framework desejado
{
  "framework": "vite"
}

// Se o seu framework salva os arquivos finais numa pasta não-padrão (ex: public)
// você pode ajustar isso no vercel.json:
{
  "outputDirectory": "public"
}

// api/middleware.js (Exemplo Next.js Edge Middleware)
export const config = {
  runtime: 'edge',
};

export default function middleware(req) {
  return Response.redirect(new URL('/novo-caminho', req.url));
}

// Adicionando cabeçalhos de controle de Cache na resposta da API Vercel
export default function handler(req, res) {
  // Cacheia na CDN por 1 hora (3600 segundos)
  res.setHeader('Cache-Control', 's-maxage=3600');
  res.status(200).json({ time: Date.now() });
}

// Exemplo usando getStaticProps no Next.js com ISR na Vercel
export async function getStaticProps() {
  const dados = await fetch('api.exemplo.com');
  return {
    props: { dados },
    revalidate: 60, // A Vercel vai revalidar a página após 60 segundos no fundo
  };
}

import Image from 'next/image';
// O componente Image integrado à Vercel 
// converte, redimensiona e faz cache da imagem globalmente:
<Image src="/foto.png" width={500} height={300} alt="Foto Otimizada" />

// api/hello.js
export default function handler(req, res) {
  // Este log será armazenado e visualizável nos Runtime Logs da Vercel
  console.log('Nova requisição recebida de IP:', req.headers['x-forwarded-for']);
  res.status(200).send('Olá!');
}

// Use logs para monitorar execuções de serverless functions e erros graves:
export default async function handler(req, res) {
  try {
    await processarPagamento();
  } catch (error) {
    console.error('[ERRO CRÍTICO] Falha no processamento:', error.message);
    res.status(500).end();
  }
}

import { kv } from '@vercel/kv';

export default async function handler(req, res) {
  // Armazenando visualizações de página direto no banco de dados KV (Redis) da Vercel
  const pageViews = await kv.incr('views:homepage');
  res.json({ pageViews });
}

import { Analytics } from '@vercel/analytics/react';

// Basta injetar o componente na raiz da sua aplicação
export default function MyApp({ Component, pageProps }) {
  return (
    <>
      <Component {...pageProps} />
      <Analytics />
    </>
  );
}
